function drag(el,drop,correct){el.addEventListener("pointerdown",e=>{el.setPointerCapture(e.pointerId);let move=x=>{let r=drop.getBoundingClientRect();drop.classList.toggle("over",x.clientX>r.left&&x.clientX<r.right&&x.clientY>r.top&&x.clientY<r.bottom)};let up=x=>{el.removeEventListener("pointermove",move);drop.classList.remove("over");let r=drop.getBoundingClientRect();if(x.clientX>r.left&&x.clientX<r.right&&x.clientY>r.top&&x.clientY<r.bottom)correct(el,drop);};el.addEventListener("pointermove",move);el.addEventListener("pointerup",up,{once:true})})}
function sequence(a){a.innerHTML="<h3>المتتابعة: ٤، ٧، ١٠، ١٣، ؟، ؟</h3><div class='dragzone' id='pool'></div><div class='dragzone'><div class='drop' data-v='16'>الخانة الخامسة</div><div class='drop' data-v='19'>الخانة السادسة</div></div>";let vals=["١٦","١٨","١٩","٢٠"];vals.sort(()=>Math.random()-.5).forEach(v=>{let c=document.createElement("div");c.className="card";c.textContent=v;c.dataset.v=v;c.draggable=true;$("pool").append(c);let d=document.querySelectorAll(".drop")[v==="١٦"?0:v==="١٩"?1:0];drag(c,d,(x,z)=>{if(x.dataset.v===z.dataset.v){z.textContent=x.textContent;z.classList.add("filled");x.remove();if(document.querySelectorAll(".filled").length===2)success("النمط ثابت: نضيف ثلاثة في كل مرة.");}else fail("راجع الفرق بين الحدود المتتالية.");});})}
